<?php get_header(); ?><main id="primary" class="sd-main sd-homepage"><?php if ( 'page-content' === sd_homepage_get( 'sd_homepage_mode' ) && have_posts() ) : ?><div class="sd-container sd-content-wrap sd-homepage-page-content"><?php while ( have_posts() ) : the_post(); the_content(); endwhile; ?></div><?php else : ?><?php foreach ( sd_homepage_sections() as $section ) { sd_homepage_render_section( $section ); } ?><?php endif; ?></main><?php get_footer(); ?>
